CREATE TABLE IF NOT EXISTS households(owner VARCHAR(190) PRIMARY KEY,created VARCHAR(190));
CREATE TABLE IF NOT EXISTS visits(ticket VARCHAR(190) PRIMARY KEY, owner VARCHAR(190), browser VARCHAR(190), expires VARCHAR(190), FOREIGN KEY(owner) REFERENCES households(owner) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS config(id VARCHAR(190) PRIMARY KEY,value LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schemes(sid VARCHAR(190),version INTEGER,status VARCHAR(190),body LONGTEXT,published_sid VARCHAR(125) GENERATED ALWAYS AS (CASE WHEN status='published' THEN sid ELSE NULL END) STORED UNIQUE,PRIMARY KEY(sid,version));
CREATE TABLE IF NOT EXISTS sources(id VARCHAR(190) PRIMARY KEY,sid VARCHAR(190),body LONGTEXT,active INTEGER);
CREATE TABLE IF NOT EXISTS vectors(id VARCHAR(190),model VARCHAR(190),checksum VARCHAR(190),body LONGTEXT,PRIMARY KEY(id,model));
CREATE TABLE IF NOT EXISTS sessions(owner VARCHAR(190) PRIMARY KEY,seen VARCHAR(190),admin_until VARCHAR(190) DEFAULT '');
CREATE TABLE IF NOT EXISTS profiles(id VARCHAR(190) PRIMARY KEY,owner VARCHAR(190),name VARCHAR(190),answers LONGTEXT,prefs LONGTEXT,updated VARCHAR(190), FOREIGN KEY(owner) REFERENCES households(owner) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS drafts(profile VARCHAR(190),sid VARCHAR(190),body LONGTEXT,updated VARCHAR(190),PRIMARY KEY(profile,sid), FOREIGN KEY(profile) REFERENCES profiles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS decisions(id BIGINT AUTO_INCREMENT PRIMARY KEY,profile VARCHAR(190),sid VARCHAR(190),body LONGTEXT,time VARCHAR(190), FOREIGN KEY(profile) REFERENCES profiles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reminders(id BIGINT AUTO_INCREMENT PRIMARY KEY,profile VARCHAR(190),signature VARCHAR(190),body LONGTEXT,wake VARCHAR(190),dismissed INTEGER DEFAULT 0,UNIQUE(profile,signature), FOREIGN KEY(profile) REFERENCES profiles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS events(id BIGINT AUTO_INCREMENT PRIMARY KEY,time VARCHAR(190),kind VARCHAR(190),entity VARCHAR(190),detail LONGTEXT);
CREATE TABLE IF NOT EXISTS traces(id BIGINT AUTO_INCREMENT PRIMARY KEY,time VARCHAR(190),route VARCHAR(190),body LONGTEXT);
CREATE TABLE IF NOT EXISTS experiments(id BIGINT AUTO_INCREMENT PRIMARY KEY,time VARCHAR(190),body LONGTEXT);
CREATE TABLE IF NOT EXISTS feedback(id BIGINT AUTO_INCREMENT PRIMARY KEY,profile VARCHAR(190),rating INTEGER,time VARCHAR(190), FOREIGN KEY(profile) REFERENCES profiles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS blobs(hash VARCHAR(190) PRIMARY KEY,name VARCHAR(190),body LONGBLOB);
CREATE TABLE IF NOT EXISTS confirmed_scans(profile VARCHAR(190) PRIMARY KEY,body LONGTEXT,FOREIGN KEY(profile) REFERENCES profiles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS checklist_items(profile VARCHAR(190),sid VARCHAR(190),item_no INT,label TEXT,ready INT,PRIMARY KEY(profile,sid,item_no),FOREIGN KEY(profile,sid) REFERENCES drafts(profile,sid) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS karnataka_directory(slug VARCHAR(190) PRIMARY KEY,name TEXT,kind VARCHAR(80),department TEXT,url TEXT,official TEXT,sid VARCHAR(190));
CREATE TABLE IF NOT EXISTS reports(id VARCHAR(190) PRIMARY KEY,profile VARCHAR(190),sid VARCHAR(190),created VARCHAR(190),body LONGBLOB,FOREIGN KEY(profile) REFERENCES profiles(id) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS member_activity(id BIGINT AUTO_INCREMENT PRIMARY KEY,profile VARCHAR(190) NOT NULL,kind VARCHAR(80),sid VARCHAR(190),body LONGTEXT,created VARCHAR(190),FOREIGN KEY(profile) REFERENCES profiles(id) ON DELETE CASCADE);
